// #endregion 📂File Tree Utilities

// #region ⚛️React
// React hooks for reactive kit data access backed by a KitStore.
// All hooks are read-only selectors; mutations go through KitStore.apply/transact.
// <KitProvider backbone?> wraps a KitStore (local/dev/remote).
// <PieceProvider guid> scopes piece hooks to a specific piece.

import { createContext, useContext, useCallback, useMemo, useRef, type ReactNode, type FC } from "react";
import { useSyncExternalStore } from "react";

// #region ⚛️KitReactTypes
// Shared type aliases for the React hook layer.

/** 🆔 Reference to a type by guid. */
export type ReactTypeId = TypeId;
/** 🆔 Reference to a design by guid. */
export type ReactDesignId = DesignId;
/** 🆔 Reference to a piece by guid. */
export type ReactPieceId = PieceId;
/** 🆔 Reference to a connection by guid. */
export type ReactConnectionId = ConnectionId;
/** 🆔 Either a type or design reference (blueprint). */
export type BlueprintId = { kind: "type"; guid: string } | { kind: "design"; guid: string };
// #endregion ⚛️KitReactTypes

// #region ⚛️BackboneKind
/** 🔧 Discriminated backbone configuration for KitProvider. */
export type BackboneKind =
  | { kind: "local"; folderPath: string }
  | { kind: "dev"; filePath: string }
  | { kind: "remote"; url: string };
// #endregion ⚛️BackboneKind

// #region ⚛️KitContext
/** 🏗️ Internal context value carrying the kit store and current snapshot. */
type KitContextValue = {
  store: KitStore;
  kit: KitImpl;
};

const KitContext = createContext<KitContextValue | null>(null);

function useKitContext(): KitContextValue {
  const ctx = useContext(KitContext);
  if (!ctx) throw new Error("useKit*() hooks must be used inside <KitProvider>.");
  return ctx;
}

/** 🏪 Returns the raw KitStore from the nearest KitProvider. */
export function useKitStore(): KitStore {
  return useKitContext().store;
}

/** 🏗️ Returns the live KitImpl instance from the nearest KitProvider. */
export function useKit(): KitImpl {
  return useKitContext().kit;
}
// #endregion ⚛️KitContext

// #region ⚛️KitProvider
/** 🏗️ Provides a reactive KitStore to the component tree.
 *
 * Accepts an explicit `store` prop (pre-built KitStore) or a `backbone`
 * descriptor that creates an InMemoryKitStore with the matching backbone.
 * Children re-render only when the store emits a change.
 */
export type KitProviderProps = {
  /** Pre-built store — use this when the caller manages the store lifecycle. */
  store?: KitStore;
  /** Convenience: backbone descriptor creates an InMemoryKitStore internally. */
  backbone?: BackboneKind;
  /** Initial kit data when using backbone (ignored when store is provided). */
  initialKit?: KitLike;
  children: ReactNode;
};

export const KitProvider: FC<KitProviderProps> = ({ store: externalStore, backbone: _backbone, initialKit, children }) => {
  const internalStoreRef = useRef<KitStore | null>(null);

  if (!externalStore && !internalStoreRef.current) {
    const kit = initialKit ? asKitInstance(initialKit) : asKitInstance({
      guid: guid(),
      name: "Untitled",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    } as KitData);
    internalStoreRef.current = new InMemoryKitStore(kit);
  }

  const store = externalStore ?? internalStoreRef.current!;

  const subscribe = useCallback(
    (onStoreChange: () => void) => store.subscribe(onStoreChange),
    [store],
  );
  const getSnapshot = useCallback(() => store.getSnapshot(), [store]);
  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);

  const value = useMemo<KitContextValue>(
    () => ({ store, kit: snapshot.kit }),
    [store, snapshot],
  );

  return KitContext.Provider
    ? createKitProviderElement(KitContext.Provider, value, children)
    : null;
};

function createKitProviderElement(
  Provider: any,
  value: KitContextValue,
  children: ReactNode,
): any {
  // Use the imported createElement from React
  const { createElement: ce } = { createElement: (globalThis as any).__semio_react_createElement };
  if (ce) return ce(Provider, { value }, children);
  // Fallback: dynamic import already pulled createElement at module top
  return (Provider as any)({ value, children });
}

