  Provider: any,
  value: KitContextValue,
  children: ReactNode,
): any {
  // Use the imported createElement from React
  const { createElement: ce } = { createElement: (globalThis as any).__semio_react_createElement };
  if (ce) return ce(Provider, { value }, children);
  // Fallback: dynamic import already pulled createElement at module top
  return (Provider as any)({ value, children });
}

